// A tiny order system — written by someone who assumes `=` makes a copy.
// Run from the repo root:
//   dotnet run csharp/02-value-vs-reference/original.cs
//
// It runs fine. No crash, no error. But watch the totals: three of the numbers
// it prints are "wrong" — or rather, they're right, and the AUTHOR is wrong
// about what the code does. The aliasing bug IS the lesson.
#nullable disable   // older codebases run with null-checking off — project 05 turns it on

Console.WriteLine("=== Surprise 1: a 'copy' that isn't ===");
var home = new Point { X = 1, Y = 2 };
var backup = home;          // "save a copy before I experiment"... except it isn't a copy
backup.X = 99;              // "only changing the backup"
Console.WriteLine($"home.X   should still be 1... it is: {home.X}");
Console.WriteLine($"backup.X was set to 99....... it is: {backup.X}");

Console.WriteLine();
Console.WriteLine("=== Surprise 2: one shared 'default' leaks everywhere ===");
var defaultTags = new List<string> { "new" };
var mug = new Order { Product = "Mug", Quantity = 2, UnitPrice = 8.00m, Tags = defaultTags };
var tee = new Order { Product = "T-shirt", Quantity = 1, UnitPrice = 15.00m, Tags = defaultTags };
mug.Tags.Add("gift-wrap");  // customer wants ONLY the mugs gift-wrapped
Console.WriteLine($"mug tags: {string.Join(", ", mug.Tags)}");
Console.WriteLine($"tee tags: {string.Join(", ", tee.Tags)}   <- who asked to wrap the t-shirt?!");

Console.WriteLine();
Console.WriteLine("=== Surprise 3: 'duplicating' an order aliases it ===");
var orders = new List<Order>();
orders.Add(mug);
orders.Add(tee);
orders.Add(mug);            // "customer ordered the mug line twice" — same object, twice!
Console.WriteLine($"3 order lines, total: {Total(orders):0.00}  (2x8 + 15 + 2x8 = 47.00, ok so far)");

// Now apply a 50% discount to the FIRST line only...
orders[0].UnitPrice = orders[0].UnitPrice / 2;
Console.WriteLine($"after 50% off line 1: {Total(orders):0.00}  (expected 39.00: 8 + 15 + 16)");
Console.WriteLine("...but line 3 IS line 1, so the discount hit both. We just gave money away.");

decimal Total(List<Order> list)
{
    decimal sum = 0;
    foreach (var o in list) sum += o.Quantity * o.UnitPrice;
    return sum;
}

class Point
{
    public int X;
    public int Y;
}

class Order
{
    public string Product;
    public int Quantity;
    public decimal UnitPrice;
    public List<string> Tags;
}

# 🏋️ Practice: Value vs Reference

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. Translate a Point (warm-up)

Add a `Translate(int dx, int dy)` method to the `Point` record in `Models.cs` that returns a **new** point shifted by that amount. `new Point(1, 2).Translate(3, 4)` gives `Point(4, 6)` — and the original point must be unchanged (it couldn't change anyway; that's the point).

Practices: adding a method to a record, building copies with `with`.

Hint: inside a record, `this with { X = ... }` copies yourself with changes. You can change two properties in one `with`.

Check it offline: add this Check test to `Tests.cs` — it should pass:
`Check.Equal(new Point(4, 6), new Point(1, 2).Translate(3, 4), "translate shifts both axes");`

### ⭐⭐ 2. Bump the quantity (core)

Add `WithExtra(int more)` to the `Order` record: it returns a copy with `more` added to the quantity. In the style of `WithDiscount`, it must be pure — the original order keeps its old quantity.

Practices: the "return a modified copy" pattern, expression-bodied methods (`=>`).

Hint: mirror `WithDiscount`'s one-liner shape, but target `Quantity` instead of `UnitPrice`.

Check it offline: add to `Tests.cs` — both should pass:
`Check.Equal(24.00m, new Order("Mug", 2, 8.00m).WithExtra(1).Total, "2+1 mugs cost 24");`
`var keep = new Order("Mug", 2, 8.00m); keep.WithExtra(5); Check.Equal(16.00m, keep.Total, "original untouched");`

### ⭐⭐ 3. Discount the whole cart (core)

Add `DiscountAll(decimal percent)` to `Cart`. It must apply the discount to *every* line — but remember: orders are immutable, so you can't loop with `foreach` and mutate. You have to **replace each slot** with a discounted copy, like `DiscountLine` does for one slot.

Practices: index-based `for` over a private list, replace-don't-mutate.

Hint: `foreach (var line in _lines) line = ...` won't compile — use `for (int i = 0; ...)` and assign `_lines[i]`.

Check it offline: add to `Tests.cs` — it should pass (16 + 15 = 31, halved = 15.50):
```csharp
var sale = new Cart();
sale.Add(new Order("Mug", 2, 8.00m));
sale.Add(new Order("T-shirt", 1, 15.00m));
sale.DiscountAll(50);
Check.Equal(15.50m, sale.Total(), "everything half price");
```

### ⭐⭐ 4. A snapshot you can trash (core)

`Cart.Lines` is a read-only *view* — callers can't change it, but it always shows the live list. Add `Snapshot()` returning a `List<Order>` that is a genuinely separate list: the caller may `Clear()` it, sort it, whatever, and the cart must not notice.

Practices: defensive copying **out** (the mirror image of the defensive copy the README talks about).

Hint: `List<T>` has a constructor that takes an existing collection and copies its items into a new list.

Check it offline: add to `Tests.cs` — it should pass:
```csharp
var c = new Cart();
c.Add(new Order("Mug", 1, 8.00m));
var snap = c.Snapshot();
snap.Clear();
Check.Equal(1, c.Lines.Count, "trashing the snapshot leaves the cart alone");
```

### ⭐⭐⭐ 5. Extend the record and follow the errors (challenge)

Add a fourth positional parameter `string Sku` to the `Order` record — first **without** a default value. Run the build and *count* the compile errors: every `new Order(...)` in `Cart.cs`... wait, there are none — but `Tests.cs`, `Program.cs` and this file's suggested tests all break. Read two of the error messages fully. Then change it to `string Sku = "SKU-0"` (a default value) and watch every error vanish. Confirm `with` and equality now include the new field.

Practices: how the compiler finds every call site for you, default parameter values, record equality over all fields.

Hint: positional record parameters accept defaults exactly like method parameters: `(..., string Sku = "SKU-0")`.

Check it offline: first version = a screenful of CS7036 errors ("there is no argument given that corresponds to..."); after adding the default, tests are green and this passes in `Tests.cs`:
`Check.True(new Order("Mug", 1, 8m) != new Order("Mug", 1, 8m) with { Sku = "SKU-7" }, "Sku participates in equality");`

### ⭐⭐⭐ 6. Money: a readonly record struct with `+` (challenge)

In `Models.cs`, write `Money` — a `readonly record struct` with `decimal Amount` and `string Currency` — and give it a `+` **operator** that adds two amounts, but throws `InvalidOperationException` when the currencies differ. So `new Money(5m, "USD") + new Money(3m, "USD")` equals `new Money(8m, "USD")`, and adding USD to EUR blows up loudly instead of producing nonsense.

Practices: writing a value type in the project's style, operator overloading, guarding invariants.

Hint: the signature is `public static Money operator +(Money a, Money b)` inside the record struct, and `a with { Amount = ... }` works on record structs too.

Check it offline: add to `Tests.cs` — all three should pass:
```csharp
Check.Equal(new Money(8m, "USD"), new Money(5m, "USD") + new Money(3m, "USD"), "same currency adds");
Check.True(new Money(2m, "USD") == new Money(2m, "USD"), "value equality for free");
Check.Throws<InvalidOperationException>(() => { var _ = new Money(1m, "USD") + new Money(1m, "EUR"); }, "mixed currencies refuse");
```

## Solutions

### 1. Translate a Point

```csharp
public record Point(int X, int Y)
{
    public Point Translate(int dx, int dy) => this with { X = X + dx, Y = Y + dy };
}
```

WHY: records may have bodies with methods, just like classes. `this with { ... }` is the record-native way to say "a copy of me, changed" — no field-by-field constructor call, and impossible to forget a field, because unlisted ones are copied automatically.

### 2. Bump the quantity

```csharp
public Order WithExtra(int more) => this with { Quantity = Quantity + more };
```

WHY: same shape as `WithDiscount` — a pure method that *returns* the change instead of performing it. Callers decide what to do with the copy; nobody who holds the original can be surprised. This With-prefix naming is a common C# convention for exactly this pattern.

### 3. Discount the whole cart

```csharp
public void DiscountAll(decimal percent)
{
    for (int i = 0; i < _lines.Count; i++)
    {
        _lines[i] = _lines[i].WithDiscount(percent);
    }
}
```

WHY: `foreach` hands you a *copy of the reference* — assigning to it wouldn't touch the list (the compiler forbids it outright). Replacing by index is the honest operation: slot `i` now points at a new, discounted record. The old records are unchanged; anyone still holding one sees exactly what they always saw.

### 4. A snapshot you can trash

```csharp
public List<Order> Snapshot() => new List<Order>(_lines);
```

WHY: `new List<Order>(_lines)` builds a fresh list object holding the same order references — and since `Order` is immutable, sharing the *items* is perfectly safe; only the *list* needed copying. This is the cheap kind of defensive copy immutability buys you: one level deep is enough.

### 5. Extend the record and follow the errors

```csharp
public record Order(string Product, int Quantity, decimal UnitPrice, string Sku = "SKU-0")
```

WHY: without the default, every 3-argument `new Order(...)` fails with CS7036 — the compiler hands you a complete TODO list of call sites, which is the safe way to extend a type (JS would have silently passed `undefined`). With `= "SKU-0"`, old calls keep compiling and mean "no SKU yet". Since positional parameters become properties, `Sku` automatically joins `with` and value-equality.

### 6. Money: a readonly record struct with `+`

```csharp
public readonly record struct Money(decimal Amount, string Currency)
{
    public static Money operator +(Money a, Money b)
    {
        if (a.Currency != b.Currency)
            throw new InvalidOperationException($"can't add {b.Currency} to {a.Currency}");
        return a with { Amount = a.Amount + b.Amount };
    }
}
```

WHY: `readonly record struct` combines everything this project taught: struct = value type (assignment copies, no aliasing possible), record = value equality and `with`, readonly = the compiler rejects any mutation. Operator overloading lets `+` read like arithmetic while still enforcing the currency rule — a wrong-currency add becomes a loud exception instead of a silent `5 + 3 = 8` across currencies, which is precisely the "money gone, no exception thrown" bug from the original, prevented by design.

// The cart OWNS its list (defensive copy in, read-only view out) and its
// orders are immutable records, so no outside code can alias its internals.
public class Cart
{
    private readonly List<Order> _lines = new();

    // Expose a read-only VIEW — callers can look, but can't Add/Remove behind our back.
    public IReadOnlyList<Order> Lines => _lines;

    public void Add(Order order) => _lines.Add(order);

    // `with { }` (no changes listed) clones the record. Because records are
    // immutable this is belt-and-braces — but it documents the intent: a NEW line.
    public void DuplicateLine(int index) => _lines.Add(_lines[index] with { });

    // Discounting REPLACES one slot with a modified copy. Even if two slots
    // once pointed at the same record, only this slot changes.
    public void DiscountLine(int index, decimal percent) =>
        _lines[index] = _lines[index].WithDiscount(percent);

    public decimal Total()
    {
        decimal sum = 0;
        foreach (var line in _lines) sum += line.Total;
        return sum;
    }
}

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// The data types. Records make "copies that are really copies" trivial,
// and immutability makes accidental sharing harmless.

// A record: equality by VALUE, copies via `with`, properties read-only by default.
public record Point(int X, int Y);

// An order line. You can't mutate it after creation — to "change" it you build
// a modified copy with `with`. That single fact kills every bug in original.cs.
public record Order(string Product, int Quantity, decimal UnitPrice)
{
    public decimal Total => Quantity * UnitPrice;

    public Order WithDiscount(decimal percent) =>
        this with { UnitPrice = UnitPrice * (1 - percent / 100m) };
}

// A struct, for contrast: a VALUE type. Assignment copies the whole thing
// automatically — no sharing is even possible. (int, bool, decimal, DateTime
// are all structs under the hood.)
public struct Pixel
{
    public int X;
    public int Y;
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

// Same three scenarios as original.cs — no surprises this time.

Console.WriteLine("=== 1: a copy that IS a copy ===");
var home = new Point(1, 2);
var backup = home with { X = 99 };   // build a changed COPY; `home` untouched
Console.WriteLine($"home:   {home}");
Console.WriteLine($"backup: {backup}");

Console.WriteLine();
Console.WriteLine("=== 2: no shared mutable defaults — records can't be mutated ===");
var mug = new Order("Mug", Quantity: 2, UnitPrice: 8.00m);
var tee = new Order("T-shirt", Quantity: 1, UnitPrice: 15.00m);
Console.WriteLine($"mug: {mug}, line total {mug.Total:0.00}");
Console.WriteLine($"tee: {tee}, line total {tee.Total:0.00}");

Console.WriteLine();
Console.WriteLine("=== 3: duplicate a line, discount ONE line, total stays honest ===");
var cart = new Cart();
cart.Add(mug);
cart.Add(tee);
cart.DuplicateLine(0);                       // a real second mug line
Console.WriteLine($"3 lines, total: {cart.Total():0.00}   (16 + 15 + 16 = 47.00)");
cart.DiscountLine(0, 50);                    // 50% off line 1 ONLY
Console.WriteLine($"after 50% off line 1: {cart.Total():0.00}   (8 + 15 + 16 = 39.00)");
Console.WriteLine($"line 3 untouched: {cart.Lines[2]}");

Console.WriteLine();
Console.WriteLine("Bonus — records compare by VALUE, like you always wished JS objects did:");
Console.WriteLine($"new Point(1,2) == new Point(1,2)  ->  {new Point(1, 2) == new Point(1, 2)}");

public static class Tests
{
    public static int Run()
    {
        Console.WriteLine("Point — records have value semantics");
        Check.True(new Point(1, 2) == new Point(1, 2), "same data compares equal with ==");
        Check.Equal(new Point(1, 2), new Point(1, 2), "Equals agrees (Check.Equal relies on it)");
        Check.True(new Point(1, 2) != new Point(1, 3), "different data compares unequal");

        Console.WriteLine("`with` — copies are really copies");
        var home = new Point(1, 2);
        var moved = home with { X = 99 };
        Check.Equal(1, home.X, "original untouched after `with` copy is changed");
        Check.Equal(99, moved.X, "copy carries the change");
        Check.Equal(2, moved.Y, "copy keeps every field it didn't change");
        var clone = home with { };
        Check.Equal(home, clone, "with { } clone is equal by value...");
        Check.True(!ReferenceEquals(home, clone), "...but is a genuinely separate object");

        Console.WriteLine("Order — computed total and discount copies");
        var mug = new Order("Mug", Quantity: 2, UnitPrice: 8.00m);
        Check.Equal(16.00m, mug.Total, "2 x 8.00 = 16.00");
        var cheap = mug.WithDiscount(50);
        Check.Equal(4.00m, cheap.UnitPrice, "discount halves the copy's price");
        Check.Equal(8.00m, mug.UnitPrice, "original price untouched — WithDiscount is pure");
        Check.Equal(0m, mug.WithDiscount(100).Total, "100% discount makes the copy free");

        Console.WriteLine("Cart — duplicating then discounting one line");
        var cart = new Cart();
        cart.Add(new Order("Mug", 2, 8.00m));
        cart.Add(new Order("T-shirt", 1, 15.00m));
        cart.DuplicateLine(0);
        Check.Equal(3, cart.Lines.Count, "duplicate adds a third line");
        Check.Equal(47.00m, cart.Total(), "total before discount: 16 + 15 + 16");
        cart.DiscountLine(0, 50);
        Check.Equal(39.00m, cart.Total(), "discounting line 1 does NOT hit its duplicate");
        Check.Equal(8.00m, cart.Lines[2].UnitPrice, "line 3 keeps the full price");
        Check.Equal(4.00m, cart.Lines[0].UnitPrice, "line 1 got the discount");

        Console.WriteLine("Struct — assignment copies automatically");
        var p1 = new Pixel { X = 1, Y = 2 };
        var p2 = p1;      // whole value copied, not a reference
        p2.X = 99;
        Check.Equal(1, p1.X, "changing the struct copy leaves the original alone");
        Check.Equal(99, p2.X, "the copy took the change");

        return Check.Summary();
    }
}
